":16000,"estimatedOutputTokens":2200,"maxOutputTokens":3072,"maxBudget":0.06,"maxModelCalls":10,"kind":"review","reviewedTaskId":"develop","inputs":[{"path":"src/temperature.js","producerTaskId":"develop"},{"path":"docs/temperature-requirements.md","producerTaskId":"clarify"}],"outputs":[],"maxReworkRounds":1},{"id":"verify","subject":"独立编写并运行温度转换函数测试","objective":"依据需求说明和审查后的实现，在 `test/temperature.test.js` 中独立编写 Node 内置测试，覆盖 0→32、100→212、常规转换和非法输入抛出错误；实际执行 `node --test test/temperature.test.js` 并报告结果，不修改开发实现文件。","assigneeId":"qa","dependencies":["develop","review"],"acceptanceCriteria":["`test/temperature.test.js` 覆盖 0→32、100→212、常规转换和非法输入抛错，至少 4 项真实测试通过","实际执行 `node --test test/temperature.test.js` 并给出命令回执"],"acceptanceChecks":[{"criterionIndex":0,"command":"node --test test/temperature.test.js","minimumTests":4},{"criterionIndex":1,"command":"node --test test/temperature.test.js"}],"handoff":{"sections":[{"key":"coverage","requirement":"列出测试覆盖的输入与边界，说明未覆盖项及风险。"},{"key":"test_evidence","requirement":"给出实际测试命令、通过/失败数量和关键输出；失败必须如实报告。"}]},"estimatedInputTokens":20000,"estimatedOutputTokens":3000,"maxOutputTokens":4096,"maxBudget":0.08,"maxModelCalls":10,"kind":"verification","inputs":[{"path":"src/temperature.js","producerTaskId":"develop"},{"path":"docs/temperature-requirements.md","producerTaskId":"clarify"}],"outputs":[{"path":"test/temperature.test.js","format":"text"}],"inScope":["test/temperature.test.js"],"outOfScope":["src/temperature.js"],"verify":["node --test test/temperature.test.js"]},{"id":"accept","subject":"经理只读验收温度转换实现","objective":"等待独立审查与 QA 测试完成，读取需求说明、实现文件和测试文件，核对 0→32、100→212、非法输入抛错及真实测试回执，给出通过项、缺口和未验证项；不修改任何文件。","assigneeId":"manager","dependencies":["clarify","review","verify"],"acceptanceCriteria":["逐项核对需求、当前文件版本、审查结论和真实测试证据，说明通过项与缺口","不把规划、未执行命令或未验证内容写成已通过"],"handoff":{"sections":[{"key":"verdict","requirement":"按需求项给出通过/不通过结论、依据和剩余缺口。"},{"key":"evidence_index","requirement":"列出核对过的文件路径、审查结论和实际测试回执；未验证项明确标出。"}]},"estimatedInputTokens":16000,